@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap');

body {
  background-color: #0d1117;
  color: #ffffff;
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  margin: 0;
  padding: 0;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

code, pre {
  font-family: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

.text-gradient {
  background: linear-gradient(90deg, #00F0FF 0%, #39FF14 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.glass-card {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.75rem;
  transition: all 0.25s ease;
}

.glass-card:hover {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(0, 240, 255, 0.4);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0, 240, 255, 0.05);
}

.cta-button {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background-color: transparent;
  color: #00F0FF;
  border: 1px solid rgba(0, 240, 255, 0.5);
  padding: 0.625rem 1.25rem;
  border-radius: 0.5rem;
  font-weight: 500;
  font-size: 0.875rem;
  transition: all 0.2s ease;
  text-decoration: none;
}
.cta-button:hover {
  background-color: rgba(0, 240, 255, 0.15);
  border-color: #00F0FF;
  box-shadow: 0 0 15px rgba(0, 240, 255, 0.3);
}

.cta-button-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background-color: #00F0FF;
  color: #0d1117;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  font-weight: 600;
  font-size: 0.875rem;
  transition: all 0.2s ease;
  text-decoration: none;
}
.cta-button-primary:hover {
  background-color: #39FF14;
  box-shadow: 0 0 20px rgba(57, 255, 20, 0.4);
}

.nav-link {
  color: #8b949e;
  font-weight: 500;
  font-size: 0.875rem;
  transition: color 0.2s ease;
}
.nav-link:hover, .nav-link.active {
  color: #ffffff;
}

/* Accordion */
.accordion-content {
  display: none;
}
.accordion-item.active .accordion-content {
  display: block;
  animation: fadeIn 0.3s ease;
}
.accordion-item {
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.5rem;
  margin-bottom: 0.5rem;
  overflow: hidden;
  transition: all 0.2s;
}
.accordion-item.active {
  border-color: rgba(0, 240, 255, 0.4);
  background: rgba(255, 255, 255, 0.02);
}
.accordion-header {
  padding: 1rem 1.25rem;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
}
.accordion-header:hover {
  background: rgba(255, 255, 255, 0.04);
}
.accordion-icon {
  transition: transform 0.3s ease;
}
.accordion-item.active .accordion-icon {
  transform: rotate(180deg);
  color: #00F0FF;
}

/* Code Block */
.code-block {
  background: #161b22;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.5rem;
  overflow: hidden;
}
.code-header {
  background: #0d1117;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  gap: 1rem;
  padding: 0 1rem;
}
.tab-btn {
  background: transparent;
  color: #8b949e;
  border: none;
  border-bottom: 2px solid transparent;
  padding: 0.75rem 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  font-family: inherit;
}
.tab-btn:hover {
  color: #fff;
}
.tab-btn.active {
  color: #00F0FF;
  border-bottom-color: #00F0FF;
}

/* Sidebar */
.sidebar-container {
  display: flex;
  min-height: calc(100vh - 64px);
}
.sidebar {
  width: 260px;
  border-right: 1px solid rgba(255, 255, 255, 0.1);
  background: #0d1117;
  transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  position: sticky;
  top: 64px;
  height: calc(100vh - 64px);
  overflow-y: auto;
  flex-shrink: 0;
}
.sidebar.collapsed {
  width: 64px;
}
.sidebar.collapsed .sidebar-text,
.sidebar.collapsed .sidebar-header {
  opacity: 0;
  pointer-events: none;
  display: none;
}
.sidebar-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 1rem;
  color: #8b949e;
  text-decoration: none;
  border-radius: 0.375rem;
  margin: 0.25rem 0.5rem;
  transition: all 0.2s;
}
.sidebar-item:hover, .sidebar-item.active {
  background: rgba(255, 255, 255, 0.05);
  color: #fff;
}
.sidebar.collapsed .sidebar-item {
  justify-content: center;
  padding: 0.5rem;
}
.main-content {
  flex: 1;
  min-width: 0;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 768px) {
  .sidebar {
    position: fixed;
    z-index: 40;
    transform: translateX(-100%);
  }
  .sidebar.mobile-open {
    transform: translateX(0);
  }
}

document.addEventListener('DOMContentLoaded', () => {

  // Mobile Nav Toggle
  const mobileMenuBtn = document.getElementById('mobile-menu-btn');
  const mobileMenu = document.getElementById('mobile-menu');
  if (mobileMenuBtn && mobileMenu) {
    mobileMenuBtn.addEventListener('click', () => {
      mobileMenu.classList.toggle('hidden');
    });
  }

  // Accordion Logic
  const accordions = document.querySelectorAll('.accordion-header');
  accordions.forEach(header => {
    header.addEventListener('click', () => {
      const item = header.closest('.accordion-item');
      if (!item) return;

      const parent = item.parentElement;
      const allItems = parent.querySelectorAll('.accordion-item');

      const isCurrentlyActive = item.classList.contains('active');

      // Close others
      allItems.forEach(i => {
        i.classList.remove('active');
        i.querySelector('.accordion-content').setAttribute('aria-expanded', 'false');
      });

      if (!isCurrentlyActive) {
        item.classList.add('active');
        item.querySelector('.accordion-content').setAttribute('aria-expanded', 'true');
      }
    });
  });

  // Package Manager Tabs
  const pmTabs = document.querySelectorAll('.tab-btn[data-pm]');
  pmTabs.forEach(btn => {
    btn.addEventListener('click', (e) => {
      const pm = e.target.dataset.pm;
      updatePackageManagers(pm);
    });
  });

  function updatePackageManagers(pm) {
    const snippets = {
      'npm': 'npm i -g @commerceforge/cli@latest',
      'yarn': 'yarn global add @commerceforge/cli@latest',
      'pnpm': 'pnpm add -g @commerceforge/cli@latest'
    };

    document.querySelectorAll('.cli-install-snippet').forEach(el => {
      el.textContent = snippets[pm];
    });

    pmTabs.forEach(b => {
      if (b.dataset.pm === pm) {
        b.classList.add('active');
      } else {
        b.classList.remove('active');
      }
    });
  }

  // Sidebar Collapse
  const sidebarBtn = document.getElementById('sidebar-collapse-btn');
  const sidebar = document.getElementById('sidebar');
  if (sidebarBtn && sidebar) {
    sidebarBtn.addEventListener('click', () => {
      sidebar.classList.toggle('collapsed');

      // Optional: Store preference in localStorage
      if (sidebar.classList.contains('collapsed')) {
        localStorage.setItem('sidebarCollapsed', 'true');
      } else {
        localStorage.setItem('sidebarCollapsed', 'false');
      }
    });

    // Check initial state
    if (localStorage.getItem('sidebarCollapsed') === 'true') {
      sidebar.classList.add('collapsed');
    }
  }
});
